'use strict';
window.OrthodoxNavigation=(()=>{
 const key='orthodox-way.navigation.v1',sidebar=document.getElementById('sidebar'),button=document.getElementById('nav-pin');let pinned=false;
 try{pinned=JSON.parse(localStorage.getItem(key)||'false')===true;}catch{}
 const groups=[['Read',[['home','⌂','Home'],['learn','▤','Learn'],['prayers','☦','Prayers'],['explore','⌘','Explore'],['saints','✧','Saints'],['icons','▣','Icons'],['services','▤','Services'],['church','⌂','Inside the church'],['church-year','◷','Church year'],['timeline','⌁','History timeline']]],['Study',[['authority','▤','Church authority'],['coverage','▤','Learning map'],['protestant-path','▤','Protestant background'],['scripture-library','▥','Scripture and Fathers'],['glossary','Α','Glossary'],['notebook','▧','Study notebook'],['journal','▧','Lesson notes']]],['Reference',[['sources','▥','Sources'],['source-guide','▤','Source guide'],['editorial','▤','Editorial review'],['offline','▤','Offline reading']]]];
 function markup(section){return groups.map(([heading,links])=>'<div class="nav-group"><p class="nav-group-label">'+heading+'</p>'+links.map(([id,icon,label])=>'<a href="#/'+id+'" class="nav-link '+(id===section?'active':'')+'" aria-label="'+label+'" title="'+label+'"'+(id===section?' aria-current="page"':'')+'><span class="nav-icon" aria-hidden="true">'+icon+'</span><span class="nav-text">'+label+'</span></a>').join('')+'</div>').join('');}
 function apply(){document.body.classList.toggle('nav-pinned',pinned);button.setAttribute('aria-pressed',String(pinned));button.setAttribute('aria-label',pinned?'Collapse navigation':'Expand navigation');button.title=pinned?'Collapse navigation':'Expand navigation';button.querySelector('path').setAttribute('d',pinned?'M15 5l-7 7 7 7M4 4v16':'M9 5l7 7-7 7M20 4v16');button.querySelector('.nav-text').textContent=pinned?'Collapse navigation':'Expand navigation';}
 function afterNavigate(){if(!pinned&&sidebar.matches(':hover'))sidebar.classList.add('nav-peek-suppressed');}sidebar.addEventListener('pointerleave',()=>sidebar.classList.remove('nav-peek-suppressed'));
 button.addEventListener('click',()=>{pinned=!pinned;if(!pinned)afterNavigate();else sidebar.classList.remove('nav-peek-suppressed');try{localStorage.setItem(key,JSON.stringify(pinned));}catch{}apply();});
 window.addEventListener('storage',event=>{if(event.key===key){pinned=event.newValue==='true';apply();}});
 const page=location.pathname.split('/').filter(Boolean)[0]||'home',section=({lesson:'learn',saint:'saints',icon:'icons',prayer:'prayers',term:'glossary',service:'services'}[page]||page);document.getElementById('nav').innerHTML=markup(section);window.OrthodoxSite?.links(document.getElementById('nav'));document.getElementById('nav').dataset.section=section;apply();
 document.querySelector('#nav').addEventListener('click',event=>{if(event.target.closest('a.nav-link')&&matchMedia('(max-width:760px)').matches){sidebar.classList.remove('open');const menu=document.getElementById('menu-toggle');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation');menu.textContent='Menu';}});
 return {markup,pinned:()=>pinned,afterNavigate};
})();
